#!/bin/bash

set -e

# env variables
VITE_APP_API_BASE_URL="${VITE_APP_API_BASE_URL}"
VITE_APP_FLUTTERWAVE_PUBLIC_KEY_TESTING="${VITE_APP_FLUTTERWAVE_PUBLIC_KEY_TESTING}"
VITE_APP_GITHUB_CLEINT_ID="${VITE_APP_GITHUB_CLEINT_ID}"
VITE_APP_EXCHANGE_RATE_KEY="${VITE_APP_EXCHANGE_RATE_KEY}"
VITE_APP_BLOG_URL="${VITE_APP_BLOG_URL}"
VITE_APP_DOCS_URL="${VITE_APP_DOCS_URL}"
VITE_APP_MIRA_API_URL="${VITE_APP_MIRA_API_URL}"
VITE_APP_DOCKER_EMAIL="${VITE_APP_DOCKER_EMAIL}"
VITE_APP_DOCKER_PASSWORD="${VITE_APP_DOCKER_PASSWORD}"
VITE_APP_MONITORING_APP="${VITE_APP_MONITORING_APP}"
VITE_APP_DATABASE_API_URL="${VITE_APP_DATABASE_API_URL}"
VITE_APP_MONITORING_API_URL="${VITE_APP_MONITORING_API_URL}"
VITE_APP_ACTIVITY_LOGS_API_URL="${VITE_APP_ACTIVITY_LOGS_API_URL}"
VITE_APP_MLOPS_API_URL="${VITE_APP_MLOPS_API_URL}"

function create_env_file
{
    echo VITE_APP_API_BASE_URL=$VITE_APP_API_BASE_URL >> .env
    echo VITE_APP_EXCHANGE_RATE_KEY=$VITE_APP_EXCHANGE_RATE_KEY >> .env
    echo VITE_APP_BLOG_URL=$VITE_APP_BLOG_URL >> .env
    echo VITE_APP_MIRA_API_URL=$VITE_APP_MIRA_API_URL >> .env
    echo VITE_APP_DOCKER_EMAIL=$VITE_APP_DOCKER_EMAIL >> .env
    echo VITE_APP_DOCKER_PASSWORD=$VITE_APP_DOCKER_PASSWORD >> .env
    echo VITE_APP_GITHUB_CLEINT_ID=$VITE_APP_GITHUB_CLEINT_ID >> .env
    echo VITE_APP_FLUTTERWAVE_PUBLIC_KEY_TESTING=$VITE_APP_FLUTTERWAVE_PUBLIC_KEY_TESTING >> .env
    echo VITE_APP_DOCS_URL=$VITE_APP_DOCS_URL >> .env
    echo VITE_APP_MLOPS_API_URL=$VITE_APP_MLOPS_API_URL >> .env
    echo VITE_APP_MONITORING_APP=$VITE_APP_MONITORING_APP >> .env
    echo VITE_APP_DATABASE_API_URL=$VITE_APP_DATABASE_API_URL >> .env
    echo VITE_APP_MONITORING_API_URL=$VITE_APP_MONITORING_API_URL >> .env
    echo VITE_APP_ACTIVITY_LOGS_API_URL=$VITE_APP_ACTIVITY_LOGS_API_URL >> .env
}


function run
{
    create_env_file
}

run